// 유럽 권역 (DESIGN.md §5.2, 층 8): 유럽 나라(1789~1914 뼈대)와 러시아 제국·소련·러시아 연방의 도형과 versions. 짝 entities 파일: data/entities/europe.yaml
// 가져와도 되는 것: lib.mjs, shared.mjs, areas/korea.mjs, areas/inner-asia.mjs, areas/china.mjs (러시아가 청·조선·외몽골을 뺀다)
// 2026-10-01 (작업 E1): 영국·프랑스·러시아 제국·소련·러시아 연방을 west 권역에서 옮겼다(나라 id는 그대로).
// 2026-10-02 (작업 E2): 1815년(빈 회의)부터 1914년 7월(1차 대전 직전)까지 유럽 권역(조각 domain, 튀르키예·캅카스 포함)의 나라를 넣었다.
//   1815~1914년 영토는 아래 '1815~1914 조각 소유표' 한곳에서 정한다: 조각(또는 선으로 나눈 조각)마다 [해, 나라] 목록을 적고, 나라별 버전은 이 표에서 만든다.
//   한 조각은 표에 한 번만 나오므로 같은 기간 한 조각을 두 나라가 가질 수 없고, 조각을 두 번 쓰거나 빠뜨리면 멈춘다.
//   영국·프랑스·러시아 제국의 1815~1914년 버전도 이 표에서 만든다(E1 버전과 도형이 같음, compare:geo로 확인). 러시아 제국은 1815~1860년 버전을 더했다.
// 2026-10-02 (작업 E3): 1789년(프랑스 혁명)부터 1814년(빈 회의 전)까지를 '1789~1814 조각 소유표'로 더했다. 소유표는 시대마다 하나이고(아래 '조각 소유표의 틀'),
//   1814년과 1815년의 단위 목록이 같은 나라는 한 버전으로 이어진다. 영국·프랑스·러시아 제국도 1789년부터 이 표에서 만든다.
// 2026-10-03 (작업 B1): 1918년(1차 대전 뒤 신생국)부터 1945년(2차 대전 종전 직후)까지를 '1918~1945 조각 소유표'(T1918)로 더했다. E2 표는 1917년까지로 늘렸다(1915년 키프로스만 바뀜).
//   1차 대전 중(1914~1918)의 전시 점령은 그리지 않고(법적 국경), 2차 대전(1939~1945)의 점령지는 중일 전쟁 점령지처럼 점령 항목(occupied_by)으로 그해 말 모습을 그린다.
//   소련의 유럽 쪽(1918~1945)도 이 표에서 만든다(E1의 1921년 무렵 고정 도형 SU_EU_1921을 대신함).
// 2026-10-03 (작업 B2): 1946년부터 1991년(냉전, 소련 해체 직전)까지를 '1946~1991 조각 소유표'(T1946)로 더했다. 소련의 유럽 쪽 1946~1991년도 이 표에서 만든다
//   (E1의 고정 도형 SU_EU_1946을 대신함, 1946~1990년 땅은 같음).
// 2026-10-04 (작업 A): 1992년(소련·유고슬라비아 해체 뒤)부터 지금까지를 '1992~현재 조각 소유표'(T1992)로 더했다. 분쟁·실효 지배 지역(크림·돈바스·트란스니스트리아·압하지야·
//   남오세티야·나고르노카라바흐·코소보)은 법적 주인 색의 지역 항목으로 떼어 내고(기준은 그 표의 머리 주석), 러시아 연방의 땅도 이 표가 정한다(도형은 E1의 RF_EU 그대로).
// 2026-10-06 (작업 D1): 1700년(대북방 전쟁·에스파냐 왕위 계승 전쟁)부터 1788년(프랑스 혁명 전)까지를 '1700~1788 조각 소유표'(T1700)로 더했다. 1789~1814 표와 다르게 나눈 조각을 쓰는 나라
//   (러시아·프로이센·폴란드-리투아니아·오스만)는 1788년과 1789년의 땅이 같으면 뒤 버전의 단위 목록으로 잇는다(LATER_LIST_SEAMS, 1789년부터의 도형이 그대로). 러시아 차르국(1700~1720)도 러시아 제국과 같은 손 도형을 쓴다.
// 2026-10-06 (작업 D2): 1600년부터 1699년(카를로비츠 조약)까지를 '1600~1699 조각 소유표'(T1600)로 더했다. 1700~1788 표에서 나눈 조각은 D1_UNITS로 이어 쓰고, 땅은 같은데 단위 이름만 달라지는
//   폴란드-리투아니아·베네치아는 1700년 이음매(LATER_LIST_SEAMS)로 1700년부터의 도형을 그대로 둔다. 러시아 차르국·러시아 제국의 1788년까지 권역 바깥선 밖은 '시베리아 진출 단계'(SIBERIA_ZONES)로 잘라 쓴다
//   1789~1917년의 러시아 제국 손 도형도 같은 단계(카자흐 3주즈 1822·1824·1854, 아이훈 1858, 중앙아시아 1866~1895, 사할린 1875, 투바 1914 등)로 이어 그려 카자흐 초원·중앙아시아·투바·사할린이
//   한꺼번에 러시아로 칠해지던 근사를 고쳤다(1789년부터 바뀐 도형은 russia.geojson의 손 도형 부분뿐). 오렌부르크주의 우랄강 남쪽·동쪽 초원도 1743년까지 비운다.
// 2026-10-06 (작업 D3): 1526년(모하치 전투)부터 1599년까지를 '1526~1599 조각 소유표'(T1526)로 더했다. 새 선은 긋지 않고 통째 조각과 앞 표들의 나눈 조각(D2_UNITS·D1_UNITS·E3_UNITS)만 써서
//   1599년과 1600년에 땅이 같은 나라는 한 버전으로 이어진다(1600년부터의 도형이 바이트까지 같음). 1600년 전 시베리아는 'SIBERIA_PRE1600' 단계(1556·1586·1594·1598)로 그린다.
// 2026-10-06 (작업 D4): 1453년(콘스탄티노폴리스 함락)부터 1525년까지를 '1453~1525 조각 소유표'(T1453)로 더했다. 새 선 11개는 이 표에서만 쓰고, 그 선으로 나눈 조각을 쓰는 나라 가운데 1525년과 1526년의 땅이 같은 것
//   (모스크바 대공국·폴란드 왕국·리투아니아 대공국·크림 칸국)은 1526년 이음매(LATER_LIST_SEAMS)로 잇는다(1526년부터의 도형이 바이트까지 같음). 1453~1525년에는 권역 바깥선 밖에 러시아 땅이 없다(RUSSIA_EAST).
// 2026-10-07 (작업 FIX1): docs/EUROPE_DRAFT.md 6절의 남은 과제(국경)를 정리했다. 선은 '조각을 가르는 선 (작업 FIX1)'에 모으고 고친 표마다 그 줄에 적었다: 페름 지방 남부·대페름(1453~1599),
//   북캅카스 산지(1700~1914, 새 묶음 항목)·테레크강 북쪽·데르벤트, 리카·야이체·바냐루카(1526~1546), 사본린나·자모시치·네체 지구·키로보흐라드주 서부·제문(1700~1914), 브레멘-페르덴·니더라우지츠(1700~1814),
//   마러머로시 동부(1526~1698), 아조프해 연안(1453~1738), 호틴(1453~1712). 동아시아 쪽은 하바롭스크 쐐기(shared.mjs의 KHABAROVSK)를 러시아 손 도형에 더했다(1860~)
// 2026-10-09 (작업 C1): 동아시아 쪽 손 도형의 중러 국경(우수리강·흑룡강·아르군강, shared.mjs의 L_USSURI·L_FUYUAN·L_AMUR_UP·L_ARGUN)을 강줄기대로 다시 긋고, 외만주(OUTER_MANCHURIA)를
//   shared.mjs로 옮겼다. 하바롭스크 쪽(KHABAROVSK)은 흑룡강 띠 가운데 연해주에 드는 곳으로 고쳐 만들고, 러시아 연방은 2008년부터 두 섬의 서쪽(ISLANDS_W)을 뺀다
// 2026-10-07 (작업 M1, 중세 1단계): 1400년부터 1452년까지를 '1400~1452 조각 소유표'(T1400)로 더했다(계획은 docs/EUROPE_DRAFT.md 8절). 앞 표들의 단위(D4_UNITS 등)를 이어 쓰고 새 선(보스포루스·노이마르크·갈리폴리 조약 땅·코민)은 이 표에서만 써서
//   1452년과 1453년의 땅이 같은 나라는 1453년 버전이 앞으로 이어진다(1453년부터의 도형이 바이트까지 같음, 부르고뉴만 1453년 이음매). 1453년 전 권역 바깥선 밖에는 러시아 땅이 없다(RUSSIA_EAST).
//   정할 점의 기본값은 그 표 앞의 M1_OPT에 모았다
// 2026-10-07 (작업 M2, 중세 2단계): 1300년부터 1399년까지를 '1300~1399 조각 소유표'(T1300)로 더했다. 1400년 표의 나눈 조각(M1_UNITS)과 앞 표들의 단위를 이어 쓰고 새 선(갈리폴리반도·시스)은 이 표에서만 써서
//   1399년과 1400년의 땅이 같은 나라는 1400년 버전이 앞으로 이어진다(1400년부터의 도형이 바이트까지 같음, 이음매 없음. 스위스·홀슈타인·툴라는 1400년 표의 근사와 달라 FIX2). 1300년 전 권역 바깥선 밖에는 러시아 땅이 없다(RUSSIA_EAST). 정할 점의 기본값은 그 표 앞의 M2_OPT
// 2026-10-07 (작업 FIX2, M3 전 정리): docs/EUROPE_DRAFT.md 6절 FIX2 목록. 1300~1525년 스위스를 가입 해대로(FIX2_OPT.swissJoin, 티치노·발레를 새 선으로 나눔), 홀슈타인 1460·툴라 1503·노이마르크 1455,
//   아일랜드를 영주령과 게일 영주들(묶음)로(1300~1541), 조지아 왕국과 카르틀리·카헤티·이메레티(1300~1810, 1700~1814 표도, 2026-10-07 운영자 승인으로 작업 FIX2b에서 켬), 노가이 오르다(1440~1555), 아테네 공국(1395~1455, 보이오티아를 새 선으로 나눔),
//   토코 가문의 아이톨리아·레프카다와 베네치아의 키클라데스, 칼마르 동맹을 1397~1447년(세 나라)과 1448년부터(덴마크·노르웨이)로 나눔. 새 선(BOEOTIA·LEVENTINA·BELLINZONA_TI·VALAIS_LOW)과 옮긴 선(NEUMARK·SKYROS)은
//   1453~1525 표가 먼저 나누고 1400·1300 표가 reuse해 1400·1453년에 단위 이름이 갈리지 않는다. 정할 점의 기본값은 FIX2_OPT·FIX2_GEORGIA(EUROPE_DRAFT.md 8.12)
// 2026-10-07 (작업 FIX3, M3 뒤 정리): docs/EUROPE_DRAFT.md 6절 'M3에서 찾은 것'의 FIX3 후보 8개. 1300년 이후 표(T1300·T1400·T1453·T1526)가 처음부터 칠한 북쪽·동쪽 땅을 실효 지배가 굳은 해(M-①(나))부터로 고치고
//   그전은 비움(운영자 결정: 근거가 약한 북쪽 숲과 사미·카렐리아·모르드바 땅은 비움, M-③): 핀란드 오스트로보트니아·남사보(1323 뇌테보리 조약)·북오스트로보트니아와 케미·토르니오 해안(1375 카스텔리 성)·카이누·북사보·북오스트로보트니아 동쪽 내륙(1595 테우시나), 스웨덴 노를란드 북부 해안(베스테르보텐 1314·노르보텐 1335)과 라프마르크(사미 땅, 라플란드 포함 1553 구스타브 바사의 직접 과세),
//   노르웨이 핀마르크(1307 바르되후스 성), 브랸스크(1310까지 루스 공국들), 민스크(1326까지 루스 공국들), 이오니아·리디아(이즈미르주 1304 에페소스·마니사주 1313 마그네시아까지 동로마, 아이든주는 1285 멘테셰의 트랄레스), 카스타모누·찬크르·볼루(1309년까지 차반 가문 = 베이국들), 니즈니노브고로드주 남부(1552년까지 비움).
//   새 선은 NIZ_S(니즈니노브고로드주 남부, 북위 55.55°)·LAPPMARK_N(라프마르크 경계)·FI14_E(북오스트로보트니아 동쪽 내륙) 셋. 정할 점의 기본값은 아래 FIX3_OPT(EUROPE_DRAFT.md 8.17)
// 2026-10-07 (작업 M4, 중세 4단계): 1000년부터 1199년까지를 '1000~1199 조각 소유표'(T1000)로 더했다. 1200년 표의 나눈 조각(M3_UNITS의 카세레스)과 앞 표들의 단위를 이어 쓰고 새 선(우에스카 HUESCA_N)은 이 표에서만 써서
//   1199년과 1200년의 땅이 같은 나라는 1200년 버전이 앞으로 이어진다(1200년부터의 도형이 바이트까지 같음, 아라곤만 1200년 이음매). 후우마이야 칼리프국과 타이파·알모라비드, 노르만 정복과 앙주 제국, 불가리아 제1제국의 몰락,
//   만지케르트 뒤 룸·다니슈멘드, 키예프 루스의 분열(1132) 등 새 항목 36개(같은 날 독립 검토 반영: 아르메니아 왕국들·동아나톨리아 베이국들, 콤네노스의 회복·킬리키아 평야·트란실바니아). 정할 점의 기본값은 그 표 앞의 M4_OPT(EUROPE_DRAFT.md 8.20)
// 2026-10-08 (작업 M5, 중세 5단계): 800년부터 999년까지를 '800~999 조각 소유표'(T800)로 더했다. 1000년 표의 나눈 조각(M4_UNITS의 우에스카)과 앞 표들의 단위를 이어 쓰고 새 선(다게스탄 DAGESTAN_N, 같은 날 독립 검토 반영)은 이 표에서만 써서
//   999년과 1000년의 땅이 같은 나라는 1000년 버전이 앞으로 이어진다(1000년부터의 도형이 바이트까지 같음, 이음매 없음). 카롤루스 제국과 베르됭(843)·프륌(855)·메르센(870)·리베몽(880) 조약의 분할, 바이킹과 데인로·웨식스의 통일(927),
