  own(whole('HR-04', 'HR-08', 'HR-09', ...minus(idsOf('SVN'), ...SI_VENETIAN, ...SI_STYRIA), 'IT-TS', 'IT-GO'), [[1789, HAB], [1809, 'france'], [1814, 'austria']]);
  own(whole(...minus(idsOf('HRV'), ...DALMATIA_ISTRIA, 'HR-19', 'HR-04', 'HR-08', 'HR-09'), ...SI_STYRIA, ...idsOf('CZE', 'SVK', 'HUN'),
    'AT-1', 'AT-2', 'AT-3', 'AT-4', 'AT-6', 'AT-9', ...AUSTRIA_RO, ...VOJVODINA), [[1789, HAB]]);
  own([RS00.제문], [[1789, HAB]]); // 제문(1718년부터 합스부르크, 작업 FIX1)
