  own(whole('IT-TN'), [[1789, HRE], [1803, HAB], [1805, HRE], [1806, RHINE], [1810, NIT], [1814, 'austria']]);

  // 이탈리아 ─────────────────────────────────────────
  // 1789년: 사르데냐 왕국(피에몬테·사보이아·니스·사르데냐섬), 제노바 공화국, 오스트리아령 롬바르디아(밀라노·만토바), 베네치아 공화국(베네토·프리울리·베르가모·브레시아),
  // 파르마·모데나 공국과 루카 공화국(묶음), 토스카나 대공국, 교황령, 나폴리·시칠리아 왕국(부르봉, two-sicilies 항목), 산마리노. 발텔리나(손드리오)는 그라우뷘덴(스위스 동맹)의 속령.
  // 1797년 치살피나 공화국(롬바르디아·모데나·볼로냐·페라라·로마냐·발텔리나·베르가모·브레시아), 리구리아 공화국. 캄포포르미오 조약으로 베네치아는 오스트리아에.
