  // 1805년 이탈리아 왕국(나폴레옹이 왕), 리구리아 프랑스 병합, 프레스부르크 조약으로 베네토가 이탈리아 왕국에. 1806년 나폴리는 조제프 보나파르트(1808년 뮈라)의 왕국, 부르봉 왕가는 시칠리아로.
