  const TUSCANY = ['IT-FI', 'IT-PO', 'IT-PT', 'IT-PI', 'IT-LI', 'IT-AR', 'IT-SI', 'IT-GR', 'IT-MS'];
  const LEGATIONS = ['IT-BO', 'IT-FE', 'IT-RA', 'IT-FC', 'IT-RN'];
