  own(whole('IT-NO', 'IT-VB'), [[1789, 'sardinia'], [1801, CIS], [1814, 'sardinia']]);
  own(whole(...SARDINIA_ISLAND), [[1789, 'sardinia']]); // 1799~1814년 사르데냐 왕은 이 섬만 다스림
  own([...whole('IT-GE', 'IT-SV', 'IT-SP'), IT_IM.임페리아], [[1789, 'genoa'], [1797, 'ligurian-republic'], [1805, 'france'], [1814, 'sardinia']]);
  own([IT_IM.망통], [[1789, 'france'], [1814, 'sardinia']]); // 망통·로크브륀: 1793년까지 모나코(프랑스 보호국), 1814년 모나코 복귀 → E2처럼 사르데냐 니스로 단순화
