  own(whole('IT-MO', 'IT-RE'), [[1789, 'parma-modena-lucca'], [1797, CIS], [1814, 'italian-duchies']]);
  own(whole('IT-LU'), [[1789, 'parma-modena-lucca'], [1814, 'italian-duchies']]); // 루카: 1799~1805 민주 공화국, 1805~1814 루카·피옴비노 공국(엘리자 보나파르트)
