  own(whole(...MARCHE), [[1789, 'papal-states'], [1808, NIT], [1814, 'naples-napoleonic']]); // 1814년 뮈라(나폴리)가 점령, 1815년 교황령(E2)
  own([...whole('IT-PG', 'IT-TR', 'IT-RI', 'IT-RM', 'IT-VT', 'VAT'), LAZIO_S.교황령], [[1789, 'papal-states'], [1809, 'france'], [1814, 'papal-states']]);
