  // 알자스-로렌은 1940년 독일이 민정장관을 두어 사실상 병합. 1942년 11월 자유 지구도 점령되어 론강 동쪽(사부아·도피네·니스·보클뤼즈·프로방스 동부·코르시카)은 이탈리아(부슈뒤론은 독일),
