  // 전선이 지나는 조각만 묶음마다 나눈다: 링 조합(1941·1942·1943년 점령 여부)마다 단위 하나
  const FRONT = [[1941, O41], [1942, O42], [1943, O43]];
  const frontBits = (m) => FRONT.filter((_, i) => m & (1 << i));
  const frontMasks = [...Array(1 << FRONT.length).keys()].slice(1).sort((a, b) => frontBits(b).length - frontBits(a).length || a - b);
  const frontName = (m) => `점령 ${frontBits(m).map(([y]) => y).join('·')}`;
