  // 1960년 독립 전과 영국 주권 기지 지역(아크로티리·데켈리아, 1960~)은 영국 땅(2026-10-04 운영자 승인, 전에는 비워 둠)
  own(whole(...idsOf('CYP')), [[1946, 'uk'], [1960, 'cyprus']]);
  own(whole('CYN'), [[1946, 'uk'], [1960, 'cyprus'], [1974, 'northern-cyprus']]);
  own(whole(...idsOf('ESB', 'WSB')), [[1946, 'uk']]);

  Object.assign(B2_UNITS, { LEN46, GO46 });
