// ── 1992~현재 조각 소유표 (작업 A) ─────────────────────────────
// 소련·유고슬라비아 해체(1991~1992)부터 지금(PRESENT년 말)까지. 버전은 그해 말 모습이고, 이 시기 국경은 지금의 행정구역이라 조각을 거의 그대로 쓴다.
// 버전 해: 1992(소련 해체 뒤 나라들, 유고슬라비아 해체: 슬로베니아·크로아티아·보스니아 헤르체고비나·마케도니아·유고슬라비아 연방 공화국, 트란스니스트리아·남오세티야)
// → 1993(체코·슬로바키아 분리, 압하지야) → 1994(나고르노카라바흐 휴전선) → 1999(코소보 유엔 관리) → 2003(세르비아 몬테네그로, 이름만) → 2006(세르비아·몬테네그로 분리)
// → 2008(코소보 독립 선언, 압하지야·남오세티야의 러시아 점령) → 2014(크림 병합, 돈바스 분리 지역) → 2019(북마케도니아, 이름만) → 2020(나고르노카라바흐 전쟁 뒤 휴전)
// → 2022(러시아의 우크라이나 침공과 4개 주 병합 선언) → 2023(아제르바이잔의 나고르노카라바흐 회복)
// 1991년 말: 소련은 12월 26일에 해체되었지만 1991년 지도는 소련으로 둔다(작업 B2의 결정 그대로. 결과 노트 참고). 해체 뒤 나라들은 1992년부터 그린다.
//   슬로베니아·크로아티아(1991년 6월 독립 선언)·마케도니아(1991년 9월)도 국제 승인(1992년 1월~1993년 4월) 전이라 1992년부터 그린다.
// 분쟁·실효 지배 표시 기준(한 기준, 결과 노트에 근거):
//   ① 땅은 국제적으로 승인된 법적 국경으로 나눈다. 법적 주인이 다스리지 못한 땅은 법적 주인 색의 지역 항목으로 떼어 낸다.
//   ② 다른 유엔 회원국이 병합을 선언했거나(크림 2014, 2022년 4개 주의 점령 지역) 유엔 회원국 상당수(대략 절반)가 독립을 승인한 땅(코소보 2008~)은
//      귀속 논쟁(claimed_by: 법적 주인과 병합국, 코소보는 세르비아와 코소보 공화국)이다. 병합국의 영토에는 넣지 않는다. 코소보 공화국 항목은 따로 영토가 없다.
//   ③ 그렇지 않은데 다른 나라의 군대가 차지하거나 국제 재판소·유엔 결의가 다른 나라의 실효 지배를 인정한 땅은 점령(occupied_by 그 나라)이다:
//      북키프로스(튀르키예, 작업 B2), 트란스니스트리아(러시아, 1992~), 나고르노카라바흐와 주변 지역(아르메니아, 1994~2019), 돈바스 분리 지역(러시아, 2014~2021),
//      압하지야·남오세티야(러시아, 2008~).
//   ④ 그 밖에 법적 주인이 아닌 세력이 휴전선 너머에서 다스린 땅은, 그 상태가 10년 넘게 이어진 것(지금까지 이어지는 것 포함)만 관계 없는 지역 항목으로 둔다
//      (압하지야 1993~2007·남오세티야 1992~2007·나고르노카라바흐 2020~2022, 유엔 관리 코소보 1999~2007. 국제 연맹 관리 자르 지역과 같은 방식). 몇 해 안에 끝난 내전 중의 분리 지역
//      (크로아티아의 세르비아계 크라이나 1991~1995, 보스니아 내전의 세력권 1992~1995, 체첸 1991~1999)은 법적 주인의 땅으로 둔다.
//   ⑤ 1만 km² 미만이라도 ②~④에 드는 곳은 그린다(남오세티야 등). 대신 그 경계의 1만 km² 미만 출입은 쪼개지 않는다(아래 근사 목록).
// 쪼개지 않은 근사(각 1만 km² 미만): 코도리 계곡 위쪽(1993~2008 조지아 정부 관할, 압하지야에 넣음), 아할고리 군과 츠힌발리 둘레 조지아계 마을(2008년까지 조지아 정부 관할, 남오세티야에 넣음),
//  트란스니스트리아 경계(드니스테르강 왼쪽의 몰도바 관할 마을 코치에리·몰로바타노우아 등은 트란스니스트리아로, 오른쪽의 벤데르·바르니차는 조각 그대로 트란스니스트리아로),
//  나고르노카라바흐 둘레의 작은 월경지(아르메니아의 아르츠바셴, 아제르바이잔의 카르키 등 4곳은 1992년부터 상대가 차지)와 2016년 4월 전투(약 8km²), 라친 회랑(2020~2023),
//  1992~1993 압하지야·카라바흐 전쟁 중의 전선, 2014년 말과 2015년 2월(데발체베) 사이의 접촉선 변화, 2022년 2~11월의 점령 범위 변화(키이우·체르니히우·수미·하르키우주 북부, 헤르손 오른쪽 기슭),
