// ── 1700~1788 조각 소유표 (작업 D1) ─────────────────────────────
// 대북방 전쟁·에스파냐 왕위 계승 전쟁 무렵(1700)부터 프랑스 혁명 전(1788년 말)까지. 계획과 정할 점은 docs/EUROPE_DRAFT.md의 '작업 D 계획' 절(운영자 승인 2026-10-06: 추천안).
// 버전은 그해 말 모습이고, 전쟁 중 점령은 그리지 않고 조약으로 넘겨진 해에 바꾼다(B1의 법적 국경 원칙. 대북방 전쟁 중 러시아의 잉그리아(1703~)·에스토니아·리보니아(1710~)·핀란드(1714~1721) 점령,
// 에스파냐 왕위 계승 전쟁 중 오스트리아의 밀라노(1706)·나폴리(1707)·사르데냐(1708) 점령과 영국·네덜란드의 에스파냐령 네덜란드 점령, 1715년 오스만의 모레아 재정복, 1716~1717년 오스트리아의
// 바나트·베오그라드 점령, 1717~1718년 에스파냐의 사르데냐·시칠리아 점령 등). 큰 국경 변화(대략 1만 km² 이상) 때만 버전을 나눈다:
// 1700 → 1701(브란덴부르크-프로이센이 프로이센 왕국, 이름만) → 1707(잉글랜드·스코틀랜드 연합, 이름만) → 1713(아드리아노플 조약: 아조프와 사마라강 남쪽 자포로자 땅은 오스만·크림 칸국. 위트레흐트 조약, 1714년 라슈타트 조약도 이 해로: 에스파냐령 네덜란드·밀라노·나폴리·사르데냐는 오스트리아,
// 시칠리아는 사보이아, 지브롤터는 영국) → 1718(파사로비츠 조약: 바나트·북세르비아·소왈라키아(올테니아)는 오스트리아, 모레아는 오스만) → 1719(리히텐슈타인 공국, 160km²지만 항목이 생김)
// → 1720(헤이그 조약: 사보이아가 시칠리아를 내놓고 사르데냐를 얻어 사르데냐 왕국. 스톡홀름 조약: 페네강 남쪽 포어포메른과 슈테틴을 프로이센에) → 1721(뉘스타드 조약: 리보니아·에스토니아·잉그리아·케크스홀름을 러시아에.
// 표트르 1세가 황제를 칭함, 이름도 바뀜) → 1723(상트페테르부르크 조약: 카스피해 서쪽 기슭을 러시아에) → 1724(이스탄불 조약: 동조지아·아르메니아·아제르바이잔 서부를 오스만에)
// → 1735(빈 예비 조약: 나폴리·시칠리아는 부르봉 왕가의 카를로, 노바라·토르토나는 사르데냐. 간자 조약과 나디르의 반격으로 러시아·오스만이 캅카스에서 물러남. 1736년 이스탄불 조약·1738년 빈 조약도 이 해로)
// → 1739(베오그라드 조약: 북세르비아·올테니아를 오스만·왈라키아에 돌려줌, 자포로자 땅·아조프는 러시아) → 1742(브레슬라우·베를린 조약: 슐레지엔을 프로이센에. 1744년 동프리슬란트 상속(약 3,100km²)도 이 해로)
// → 1743(오보 조약: 퀴미강 동쪽 핀란드를 러시아에) → 1766(로렌 공국이 프랑스에) → 1768(베르사유 조약: 코르시카를 프랑스에, 약 8,700km²지만 따로 둠) → 1772(1차 폴란드 분할)
// → 1774(퀴췩카이나르자 조약: 부크강·드니프로강 사이와 카바르다를 러시아에, 크림 칸국 독립) → 1775(부코비나를 오스트리아에) → 1783(크림 칸국을 러시아가 병합). 1789년부터는 '1789~1814 조각 소유표'.
