// 묶음과 따로 둔 나라(운영자 승인 2026-10-06): 신성 로마 제국은 1789~1806년처럼 영방 묶음 하나(합스부르크 세습령·프로이센 땅·스웨덴령 포메른·덴마크 왕의 홀슈타인·로렌 공국은 따로),
// 이탈리아는 사보이아(사르데냐)·제노바·베네치아·토스카나·교황령·파르마·모데나·루카(묶음)·산마리노를 따로. 크림 칸국(오스만의 종주, 1774~1783 독립)과 로렌 공국(1766년 프랑스)은 새 항목.
