// 일부러 비운 곳(빈 땅 검사에서 그해만 뺌): 1789~1814와 같이 스발바르·얀마옌·프란츠요제프 제도(무주지)·몰타(기사단령), 조지아 왕국들(작업 FIX2부터 FIX2_GEORGIA가 true면 그림)·아제르바이잔과 다게스탄의 칸국들·아르메니아·에리반·나흐치반
// (페르시아 종주, 1724~1734년은 오스만·러시아), 1773년까지 카바르다·체첸·잉구시·북오세티야(카바르다는 1739년 베오그라드 조약으로 러시아·오스만 사이 완충지, 1774년 퀴췩카이나르자 조약으로 러시아).
// 2026-10-07(작업 FIX1): 퀴췩카이나르자 조약으로 넘어간 것은 카바르다뿐이다. 북오세티야는 같은 해 오세티야 장로들의 합의로 러시아, 체첸·인구시는 '북캅카스 산지 공동체 (묶음)'
// (인구시는 1810년, 체첸의 테레크강 남쪽은 1859년)으로 그린다(비워 두면 둘레가 러시아 땅이 된 1806년부터 생성기의 틈새 구멍 메우기가 러시아로 메움). 테레크강 북쪽(체첸 북부·다게스탄 북부의 키즐랴르)은
// 1723년(상트페테르부르크 조약, 성십자가 요새 1722)부터 러시아로, 1735년 간자 조약과 키즐랴르 요새 뒤에도 러시아(전에는 다게스탄째 1806년까지 비운 오류). 데르벤트(DERBENT)는 1723~1734년 러시아
// 2026-10-07(작업 FIX1)에 고친 것: 브레멘-페르덴(1719년까지 스웨덴)·니더라우지츠(작센)·사본린나(1743 러시아)·자모시치(1772 오스트리아)·네체 지구의 대폴란드 쪽(1772 프로이센)·키로보흐라드주 서부(폴란드)·제문(1718 합스부르크)·
