// - 발칸·헝가리: 카니자(잘라주 남부, 1600~1690 오스만)와 에스테르곰(1605~1683 오스만, 조약상 1698년까지, 약 1천km²)은 주째 합스부르크, 우이바르 에얄레트·노그라드는 니트라주·노그라드주 통째로 1664~1698년 오스만
//   (니트라주 북부·중부의 니트라·레비체·흘로호베츠·토폴차니 쪽 약 3천km² 이상은 1664년부터 합스부르크였음, 근사. 넷의 합은 약 1만 km²라 2026-10-06 D2 검토 반영으로 나눔),
//   하이두비하르주는 비하르와 함께(트란실바니아 → 1664 오스만), 루고시-커런세베시 바나트(1658년까지 트란실바니아, 약 5천km²)는 카라스세베린주째 오스만,
//   세니(리카센주 해안, 합스부르크, 약 1천km²)는 리카와 함께 오스만, 비엘로바르빌로고라주(약 2,600km²)는 오스만, 크르크·체레스·라브섬(베네치아)은 1700~1788 표처럼, 마카르스카 해안(1646년까지 오스만, 약 500km²)은 베네치아,
//   클리스(1648)와 1671년 '새 땅'(약 3천km²)은 1699년, 파르가(에피루스 해안의 베네치아 땅, 약 200km²)는 에피루스째 오스만, 티노스섬(1715년까지 베네치아, 약 200km²)은 키클라데스째 오스만, 크레타의 수다·스피날롱가·그람부사 요새(1715년까지 베네치아)는 오스만,
//   체르보노그로드 군(테르노필주 남부, 포딜리아, 약 3천km²)은 1672~1698년에도 폴란드, 빈니차주 서부(바르·샤르호로드·모힐리우포딜스키, 포딜리아 주, 약 5천km²)는 브라츨라우와 함께 1649~1659년 헤트만국·러시아,
//   키로보흐라드주 가운데(시뉴하강 동쪽의 브라츨라우 남쪽 초원, 1672~1698 오스만 쪽)는 자포로자 땅과 함께(시뉴하강 서쪽은 2026-10-07 작업 FIX1에서 브라츨라우 주와 함께 나눔)
// - 러시아·우크라이나: 벨리(트베리주)·세베시·네벨·우스뱌티(프스코프주)·벨리시(스몰렌스크주)는 2026-10-06 D2 검토 반영으로 나눔(위 선과 소유표). 전에는 '1580~1667 폴란드'로 잘못 적고 러시아로 둔 근사였다,
//   세르페이스크(칼루가주, 1618~1634)는 러시아, 수미·아흐티르카(1647년 경계 획정 전 폴란드 주장, 1650년대 슬로보다 정착)와 하르키우주 서부(크라스노흐라드 쪽 초원)는 러시아, 루한스크주(돈 코사크)는 러시아, 도네츠크주 남서부(칼미우스강, 노가이 초원)는 2026-10-07 작업 FIX1에서 크림 칸국으로 고침(전에는 자포로자 땅)
