// - 캅카스: 데르벤트(1606년까지 오스만, 1612 조약)는 2026-10-07 작업 FIX1에서 DERBENT로 나눔, 탈리시 남부(1590년에도 페르시아)는 아제르바이잔 조각째 1611년까지 오스만, 트빌리시의 오스만 수비대는 카르틀리째 비움
// 1699년과 1700년 사이에 바뀌어 보이던 브레멘-페르덴(1719년까지 스웨덴)·니더라우지츠(1815년까지 작센)는 2026-10-07 작업 FIX1에서 1700~1814년 표를 고쳐 이어진다.
