// ── 1526~1599 조각 소유표 (작업 D3) ─────────────────────────────
// 모하치 전투(1526)부터 1599년 말까지. 계획과 정할 점은 docs/EUROPE_DRAFT.md의 '작업 D 계획' 절(7.3 운영자 승인 2026-10-06, 7.8 D3 정할 점). 1600년부터는 '1600~1699 조각 소유표'(작업 D2).
// 새 선은 긋지 않았다: 조각을 통째로 쓰거나 1600~1699·1700~1788·1789~1814 표에서 나눈 조각(D2_UNITS·D1_UNITS·E3_UNITS)을 이어 써서, 1599년과 1600년에 땅이 같은 나라는 단위 목록도 같아 한 버전으로 이어진다(이음매가 필요 없음).
// 버전은 그해 말 모습이고, 전쟁 중 점령은 그리지 않고 조약으로 넘겨진 해에 바꾼다(정할 점 ⑦). 휴전은 5년 이상이면 조약으로 보고(1547 아드리아노플 5년 휴전), 3년 휴전(1570 폴란드-러시아, 1583 플류사, D2의 발리에사르)은 그리지 않는다.
// 그리지 않은 점령: 1527~1529 페르디난트의 부다, 1536~1559 프랑스의 사부아·브레스·피에몬테(1538년 니스 휴전(10년)의 현상 유지를 1544년 크레피 화약이 뒤집어 프랑스가 사보이아 공작에게 돌려주기로 함, 정할 점 D3-⑩),
// 1536~1575 에스파냐(제국군)의 아스티·베르첼리, 1544~1550 잉글랜드의 불로뉴, 1553~1559 프랑스의 코르시카, 1555~1557 제국군·피렌체의 시에나, 1558~1582 러시아의 리보니아(타르투·나르바 등)와 1563~1579 폴로츠크,
// 1581~1595 스웨덴의 나르바·이반고로드 밖 잉그리아·케크스홀름, 1541~1546 오스만의 부다(1547 휴전으로), 1552~1561 오스만의 테메슈바르·리포바·솔노크·비로비티차·노그라드(1562 조약으로), 1593~1606 장기 전쟁 중의 점령(아래 1596년 근사 밖),
// 1595 미하이 용감공의 트란실바니아·몰다비아.
// 큰 국경 변화(대략 1만 km² 이상) 때 버전을 나눈다:
// 1526(모하치 전투 뒤: 페르디난트 1세가 보헤미아·왕령 헝가리·크로아티아, 서포여이 야노시가 동헝가리 왕국, 오스만이 스렘·오시예크·리카) → 1532(브르타뉴 합병 칙령)
// → 1535(밀라노의 스포르차 가문이 끊겨 카를 5세가 차지, 1540·1546 펠리페에게 봉토) → 1538(술레이만 1세의 몰다비아 원정: 벤데르(티기너)와 부자크를 오스만 직할령으로)
// → 1542(아일랜드 왕국, 이름만) → 1543(카를 5세가 헬데른·흐로닝언·드렌터(벤로 조약 1543, 흐로닝언 1536)와 위트레흐트·오버레이설(1528)을 얻어 17주) → 1545(파르마·피아첸차 공국, 이름만에 가까움)
// → 1547(아드리아노플 휴전(5년): 1541년 부다 함락으로 오스만 직할령이 된 부다·페스트·도나우-티서강 사이·바치카·세게드와, 1543~1545년 정복한 페치·시클로시·세케슈페헤르바르·톨너·포제가를 페르디난트가 인정. 모스크바 대공국이 차르국, 이름만)
// → 1552(카잔 병합. 메스·툴·베르됭 세 주교령을 프랑스가 차지(D2처럼 1552년, 1648년 인정)) → 1555(아마시아 조약: 반·아으르(바야지트)를 오스만에. 카르스는 중립지로 1590년)
// → 1556(아스트라한 병합과 대노가이 오르다·바시키르의 신속(1554~1557), 정할 점 D3-⑨. 카를 5세의 퇴위로 네덜란드·프랑슈콩테가 펠리페 2세의 에스파냐 땅) → 1557(펠리페 2세가 시에나를 코시모 1세에게 봉토로 줌)
