// 이름(항목): 카스티야·아라곤(1479 에스파냐)·튜턴 기사단국(1525 프로이센 공국)·칼마르 동맹(1524 덴마크-노르웨이)·중세 스웨덴 왕국(1523 스웨덴 왕국)은 renames로 잇는다(정할 점 ⑩, 같은 색).
// 종속(정할 점 ⑧, D4-③): 주권 왕조·국가가 공물·종주권만 인정한 경우는 따로 그리고(관계는 relations.yaml), 종주국 안의 자치 단위(코사크·칼미크·분봉 공국)는 종주국 땅으로 칠한다.
// 따로 그린 나라: 몰다비아·왈라키아·크림 칸국·라구사(기존 예외)와 세르비아 전제공국·보스니아·헤르체고비나·모레아·트레비존드·키프로스·카잔 칸국·랴잔·프스코프·노브고로드·뱌트카, 1466년부터 폴란드 왕의 봉토가 된 튜턴 기사단국
// (제2차 토룬 조약으로 맺은 주권 국가의 봉신 관계라 따로, 1525년부터 프로이센 공국도 같음). 둘카디르 베이국(1515~1521 오스만 종주, 자기 베이)도 따로 그리고 1522년 병합에 오스만(맘루크 종속기인 1514년까지는 D4-⑪대로 비움).
// 종주국 땅으로 칠한 자치 단위: 모스크바 대공의 분봉 공국 야로슬라블(1463)·로스토프(1474), 폴란드 왕관 안의 마조프셰 공국(피아스트 가문의 왕관 봉토, 1526년까지 차례로 왕관령에 합쳐짐), 덴마크 왕의 봉토 슐레스비히 공국,
// 1515년 스스로 신속한 쿠르드 에미르국(오스만 안의 자치 산자크). 대페름(1471년까지 노브고로드에 형식상 종속된 토착 공)은 2026-10-07 작업 FIX1에서 따로 그리고(1472년 원정부터 모스크바), 페름 지방 남부는 비움(1558년 러시아, D3).
// 일부러 비운 곳: 1526~1599 표와 같은 곳(스발바르·얀마옌·프란츠요제프 제도·몰타·아제르바이잔·아르메니아·다게스탄·북캅카스 산지·모르도바·펜자·탐보프·오렌부르크 초원·보로네시·벨고로드·하르키우·페름 지방 남부(노가이 땅은 작업 FIX2부터 그림. 조지아는 FIX2_GEORGIA가 true면 그리고 1490년부터 삼츠헤는 비움, 작업 FIX2b부터 켬),
// 반·아으르·카르스·아르다한·이으드르·아르트빈 동부), 1474년까지 체르케스 해안(체르케스 공국들), 1501년 대오르다가 무너진 뒤 그 땅(볼고그라드·사라토프·돈 초원), 1514년까지 아크코윤루·사파비의 동아나톨리아(디야르바크르·에르주룸·에르진잔·비틀리스 등),
// 1514년까지 둘카디르(마라시, 맘루크 종속 베이국), 1515년까지 맘루크 술탄국과 그 종속국 라마단(아다나·하타이·가지안테프·말라티아·아드야만·우르파·마르딘). 맘루크·아크코윤루·사파비는 중동의 나라라 항목을 두지 않고, 그 종속 베이국도 종주국을 그리지 않아 비운다(정할 점 ③·D4-⑪).
//   (작업 FIX4) 1453~1498년 페초라강 유역(코미 북부·네네츠, 1499 푸스토제르스크), 1453~1465년 테르스키 해안, 콜라반도의 나머지(정할 점 FIX4-③)
// 쪼개지 않은 근사(각 1만 km² 미만):
// - 서유럽: 칼레(1558년까지 잉글랜드)와 불로뉴(1477년까지 부르고뉴)는 파드칼레도째(D3-⑫), 아미앵·생캉탱(솜강 도시들: 1463 루이 11세가 되삼, 1465 콩플랑 조약으로 돌려줌, 1471 아미앵 프랑스)은 솜도째 1481년까지 부르고뉴,
//   오세르·마코네(1435~1477 부르고뉴)와 느베르는 프랑스, 샤롤레(1493~1684 합스부르크)는 손에루아르도째 1482년부터 프랑스, 겔데른(1473~1477·1481~1492 부르고뉴·합스부르크)·위트레흐트 주교령(부르고뉴의 보호)·리에주는 신성 로마 제국 묶음,
//   프리슬란트(1498~1515 작센의 세습 총독, 1515 카를이 삼)는 1523년까지 묶음·1524년부터 합스부르크령 네덜란드, 앞오스트리아(브라이스가우·준트가우, 1469~1474 부르고뉴에 저당)는 묶음(D1~D3과 같음),
//   루시용·세르다뉴(1462~1493 프랑스에 저당·점령)는 아라곤·에스파냐(저당은 그리지 않음, D2 기준), 베아른·바스나바르(나바라 왕국 북부)는 프랑스(D3와 같음), 몰타(1530년까지 시칠리아 왕국)는 비움(D3와 같음),
//   카나리아 제도(그란카나리아 1483·라팔마 1493·테네리페 1496)와 멜리야(1497)·지브롤터(1462)는 처음부터 카스티야, 알메리아·과딕스·바사(1489 엘 사갈의 항복 조약)는 그라나다 묶음으로 1492년,
//   오크니·셰틀랜드(1468·1469 노르웨이 왕이 저당, 1472 스코틀랜드 병합)는 처음부터 스코틀랜드, 베릭(1461~1482 스코틀랜드)은 노섬벌랜드째 잉글랜드, 홀슈타인(1460 리베 조약 전 샤우엔부르크 백작)은 1459년까지 신성 로마 제국(작업 FIX2에서 고침),
//   스웨덴 왕국과 핀란드는 칼마르 동맹 왕이 스웨덴을 다스린 해(1457~1464·1497~1501·1520~1521)도 따로(정할 점 D4-④)
// - 스위스·이탈리아: 스위스는 작업 FIX2에서 가입 해대로 고침(FIX2_OPT.swissJoin: 티치노 레벤티나 1480(1441 저당)·벨린초나 1503·남부 1516, 저지 발레 1477, 프리부르 1453~1477 사보이아 등). 발텔리나(1512 그라우뷘덴)는 1516년(프리부르 영구 평화 조약)부터 스위스,
//   프리크탈(아르가우 북부, 1802년까지 합스부르크)·사르간스(1483)·라인탈(1490)·몽테(1477~1535 사보이아)·10관할구 동맹의 합스부르크 땅은 칸톤 조각째(근사),
//   그랑송·오르브·에글(1475·1476 베른)은 보째 사보이아, 아스티(오를레앙 가문·프랑스 왕령)와 살루초는 사보이아, 몬페라토와 만토바는 밀라노(정할 점 ②), 크레모나(1499~1509 베네치아)와 크레마(1449~1797 베네치아)는 크레모나주째 밀라노·프랑스,
//   파르마·피아첸차(1512 교황 점령, 1515 비테르보 합의로 프랑스, 1521 교황)는 1525년까지 밀라노·프랑스, 폴레시네(로비고, 1484 바뇰로 조약까지 페라라)·라벤나(1441~1509 베네치아)·로마냐 도시들(1503~1509 베네치아)은 베네치아·교황령째 D3와 같게,
//   피사(1494~1509 독립)는 피렌체, 볼로냐(벤티볼리오 가문, 1506 교황 직할)·우르비노·카메리노는 교황령, 베네벤토·폰테코르보(교황령 비지)는 나폴리, 제노바는 밀라노(1464~1478·1487~1499)·프랑스(1458~1461·1499~1512·1515~1522)의 주권 아래였어도 따로(정할 점 D4-⑤)
// - 독일·폴란드·리투아니아: 노이마르크(1402~1455 튜턴 기사단에 저당, 1455 쾰른 조약으로 브란덴부르크가 되삼)는 작업 FIX2에서 1454년까지 기사단국으로 고침, 라우엔부르크-뷔토우(1466년까지 기사단, 뒤 포메른의 폴란드 봉토)는 포메른,
//   미하우프·루바바 땅(1466 왕령 프로이센)은 프로이센 쪽, 오시비엥침(1457)·자토르(1494) 공국은 처음부터 폴란드, 부르겐란트(1463 비너노이슈타트 조약으로 프리드리히 3세가 지킨 서헝가리 영지)는 헝가리, 프레크무레는 오스트리아 쪽,
//   호멜(1503~1535 모스크바)은 리투아니아(D3와 같음), 도로고부시(1503 모스크바)는 스몰렌스크주 서부째 1522년, 세베시(1535 세움)는 D3와 같게 리투아니아, 툴라주(1503년까지 랴잔, 작업 FIX2) 서부의 오도예프·벨료프(1494 모스크바)와 북쪽 알렉신 쪽은 툴라주째(근사),
//   벨리키예루키(노브고로드·모스크바)는 프스코프 공화국, 1471년 코로스틴 조약의 드비나 땅 일부(범위 불명, 정할 점 D4-⑥)는 노브고로드
// - 헝가리·발칸: 샤바츠·마치바(1459 오스만, 1476 헝가리, 1521 오스만)는 세르비아·오스만, 리브노·글라모치(서보스니아, 1480년대 오스만)는 야이체 바나트와 함께 1525년까지 헝가리, 클류치·산스키모스트(우나사나 칸톤의 보스니아 왕국 땅, 1463 오스만)는 비하치와 함께 헝가리,
//   리카(1527)·야이체·바냐루카(1527~1528)는 1525년까지 헝가리, 1526년부터 합스부르크(1547년 오스만, 2026-10-07 작업 FIX1에서 D3 표를 고침), 크닌·클리스 등 달마티아 내륙(1522·1537 함락)은 1525년까지 헝가리(1526년 D3 근사에서 오스만),
//   제타는 1456년까지 세르비아 전제공국(1421년 합침), 크르노예비치 공국(1451~1496, 베네치아 보호·1479년부터 오스만에 공납)은 1456년부터 오스만, 헤르체그노비(1482)와 헤르체고비나 공국의 남은 땅은 1466년 오스만,
//   두러스(베네치아, 1501 함락·1503 조약)와 레즈허(베네치아, 1479)는 크루여가 있는 두러스주·레즈허주째 레저 동맹으로 1479년까지, 크루여(1468~1478 베네치아 수비대)는 레저 동맹째,
//   아테네 공국(아차이우올리 가문, 오스만에 공물)은 작업 FIX2에서 1455년까지 아티카·보이오티아로 그림, 에우보이아(네그로폰테, 1470 함락·1479 조약)와 렘노스(1464~1479 베네치아)·레스보스(1462까지 가틸루시)·키오스(1566까지 제노바 마오나)는 오스만,
//   낙소스 공국(크리스포 가문, 1537년까지 베네치아의 봉신, 그 뒤 오스만에 공물)과 베네치아의 키클라데스 섬들은 작업 FIX2부터 베네치아(1540년 조약까지, D3), 모돈·코론·나바리노(1500 함락, 1503 조약)·나우플리오·모넴바시아(베네치아)는 모레아째,
//   케팔로니아·자킨토스(토코 가문, 1479 오스만, 1485·1500 베네치아)는 베네치아, 레프카다(1479)는 오스만, 킬리아(1448~1465 헝가리 수비대)는 몰다비아,
//   포쿠티아(1490·1502 몰다비아 점령)는 폴란드, 브러일라는 왈라키아(D3와 같음). 호틴은 1526년 뒤에도 몰다비아(2026-10-07 작업 FIX1에서 D2·D3·D1 표를 고쳐 이어짐)
// - 러시아·흑해·아나톨리아: 테오도로 공국(만구프, 1475)과 쳄발로는 크림 칸국, 1475년 뒤 카파 에얄레트(오스만 직할)는 크림 칸국(D3와 같음), 타만의 마트레가(1482 오스만)는 쿠반째 대오르다·크림 칸국,
