// ── 1200~1299 조각 소유표 (작업 M3, 중세 3단계) ─────────────────────────────
// 1200년부터 1299년 말까지. 계획과 정할 점은 docs/EUROPE_DRAFT.md의 '작업 M 계획'(8절, M3 정할 점은 8.15). 1300년부터는 '1300~1399 조각 소유표'(작업 M2).
// 통째 조각과 앞 표들의 나눈 조각(M2_UNITS·M1_UNITS·D4_UNITS·D3_UNITS·D2_UNITS·D1_UNITS·E3_UNITS와 E2의 나눈 조각)을 이어 쓰고, 새 선은 카세레스(CACERES_N) 하나만 이 표에서 쓴다.
// 그래서 1299년과 1300년의 땅이 같은 나라는 단위 목록도 같아 1300년 버전이 앞으로 이어진다(1300년부터의 도형이 바이트까지 같음, 이음매 없음). 1300년 표(M2)가 근사로 둔 땅은
// 그 근사를 이 표에서도 이어 1300년에 갑자기 바뀌지 않게 하고, 근사를 시작한 해(관련 사건 해)를 아래 'T1300 근사와의 이음'과 정할 점 M3-⑯에 적었다(M2-⑮와 같은 방식).
// 버전은 그해 말 모습이다. 넘김 해 기준은 M1·M2와 같다(정할 점 M-①: 조약·매매·상속·봉토 수여 문서의 해, 조약 없는 정복은 실효 지배가 굳은 해, 나라가 무너지면 그해 말 차지한 쪽, 5년 넘는 휴전은 조약).
// 큰 국경 변화(대략 1만 km² 이상) 때 버전을 나눈다(53개, 시작 1200 빼고. 1만 km² 미만 변화는 사건이 일어난 해의 다음 버전 해에 묶고, 사건보다 앞선 해에 묶지 않음. 괄호 안이 사건 해):
// 1201(발데마르 2세의 홀슈타인·뤼베크·함부르크, 바르나) → 1202(룸의 에르주룸·바이부르트: 살투크 왕조, 작업 FIX4) → 1204(제4차 십자군: 라틴 제국·테살로니키 왕국·니케아·트레비존드·베네치아의 크레타, 필리프 2세의 노르망디·멘·앙주·푸아투 북부·리무쟁·페리고르, 칼로얀의 마케도니아)
// → 1205(에피루스·아카이아·아테네, 투렌(시농·로슈), 필리포폴리스가 불가리아, 베네치아의 두러스·라구사) → 1206(조지아의 카르스, 룸의 라오디케이아(작업 FIX4)) → 1207(룸의 안탈리아, 낙소스 공국, 테라 마리아나(리보니아), 스키로스)
// → 1212(라스나바스데톨로사 뒤 시우다드레알) → 1214(카스티야의 알카라스(1213), 룸의 시노프와 니케아의 파플라고니아 해안, 에피루스의 코르푸, 예르시카·셀로니아(1209·1214), 스피시 조약의 할리치나(칼만))
