  own(whole('BIH-2889', 'BIH-2890', 'BIH-2891', 'BIH-4806', 'BIH-2226'), [[1200, BOS]]);
  own(whole('BIH-2887', 'BIH-4801', 'BIH-4804', 'BA-SRP', 'BA-BRC'), [[1200, BOS], [1254, HUN]]); // 우소라·솔리
