  // 헝가리 왕국 ─────────────────────────────────────
  // 엠레·라슬로 3세·언드라시 2세(1222 금인 칙서)·벨러 4세(1241 모히 전투, 1241~1242 몽골의 점령은 그리지 않음)·이슈트반 5세·라슬로 4세·언드라시 3세. 크로아티아는 동군(헝가리 땅으로 그림)
  const TRANSYLVANIA_RO = ['RO-AB', 'RO-BN', 'RO-BV', 'RO-CJ', 'RO-CV', 'RO-HD', 'RO-HR', 'RO-MS', 'RO-SB', 'RO-SJ', 'RO-MM'];
