  own([...whole('IT-AT', 'IT-BG', 'IT-NO', 'IT-VB', 'IT-CR', 'IT-CO', 'IT-LO', 'IT-SO', 'IT-VC', 'IT-PC', 'IT-BS', 'IT-PR', 'IT-PV', 'IT-VR', 'IT-VI', 'IT-BL', 'IT-MN', 'IT-PD', 'IT-TV',
    'IT-MO', 'IT-RE', 'IT-LU', 'IT-FE', 'IT-MS', 'IT-PT', 'IT-AR', 'IT-PI', 'IT-LI'), AL00.알레산드리아, AL00.토르토나], [[1200, IMS]]);
  own(whole('IT-UD', 'IT-PN'), [[1200, HRE]]); // 아퀼레이아 총대주교령
