const M5_UNITS = {}; // 이 표에서 나눈 조각 가운데 476~799 표(작업 M6)가 다시 쓰는 것 (블록 끝에서 채움. 2026-10-08 작업 M6)
// ── 800~999 조각 소유표 (작업 M5, 중세 5단계) ─────────────────────────────
// 800년(카롤루스의 황제 대관)부터 999년 말까지. 계획과 정할 점은 docs/EUROPE_DRAFT.md의 '작업 M 계획'(8절, M5 정할 점은 8.23). 1000년부터는 '1000~1199 조각 소유표'(작업 M4).
// 통째 조각과 앞 표들의 나눈 조각(M4_UNITS·M3_UNITS·M2_UNITS·M1_UNITS·D4_UNITS·D3_UNITS·D2_UNITS·D1_UNITS·E3_UNITS와 E2의 나눈 조각)을 이어 쓰고, 새 선은 다게스탄(DAGESTAN_N, 같은 날 독립 검토 반영) 하나만 이 표에서 쓴다.
// 그래서 999년과 1000년의 땅이 같은 나라는 단위 목록도 같아 1000년 버전이 앞으로 이어진다(1000년부터의 도형이 바이트까지 같음, 이음매 없음). 1000년 표(M4)가 근사로 둔 땅은
// 그 근사를 이 표에서도 이어 1000년에 갑자기 바뀌지 않게 하고, 근사를 시작한 해(관련 사건 해)를 정할 점 M5-⑳에 적었다(M3-⑯·M4-⑱과 같은 방식).
// 버전은 그해 말 모습이다. 넘김 해 기준은 M1~M4와 같다(M-①, 운영자 승인 2026-10-07: 조약·문서의 해(베르됭 843·프륌 855·메르센 870·리베몽 880·앙제 851·콩피에뉴 867·생클레르쉬르엡트 911·본 921 등),
// 조약 없는 정복은 실효 지배가 굳은 해, 나라가 무너지면 그해 말 차지한 쪽, 이른 시기는 연대기 기사 해(앵글로색슨 연대기·원초 연대기·프랑크 왕국 연대기·풀다 연대기·레기노·스킬리치스 등)).
// 큰 국경 변화(대략 1만 km² 이상) 때 버전을 나눈다(1만 km² 미만 변화는 사건이 일어난 해의 다음 버전 해에 묶고, 사건보다 앞선 해에 묶지 않음. 항목이 시작하는 해는 예외(M3-⑮와 같음)). 버전 해와 해마다 바뀐 넓이는 결과 노트:
// 805(크룸이 아바르의 티서강 평원을 차지, 바르셀로나(801)) → 806(팜플로나가 프랑크에 복속: 프랑크 왕국 연대기) → 809(크룸의 세르디카) → 813(아쇼트 1세의 타오-클라르제티) → 816(30년 화약의 자고라) → 824(론세스바예스 뒤 팜플로나 왕국)
// → 825(엘렌던 전투 뒤 웨식스의 켄트·서식스·서리·에식스) → 827(크레타 토후국(항목이 시작하는 해), 오무르타그의 스렘·베오그라드) → 829(에그버트의 머시아 정복, 비르카의 스베아 왕(안스가르 전기)의 스베알란드·고틀란드) → 830(위글라프의 머시아 회복) → 831(팔레르모, 시칠리아 토후국(항목이 시작하는 해))
// → 833(대모라비아: 모이미르 1세가 니트라를 합침) → 836(필리포폴리스) → 838(에텔쾨즈의 마자르(항목이 시작하는 해)) → 842(프레시안의 마케도니아·알바니아, 고티아(841), 아그리젠토) → 843(베르됭 조약, 메시나, 알바 왕국(renames))
// → 851(앙제 조약의 브르타뉴 왕국) → 855(프륌 조약: 로타르 2세·루도비코 2세·프로방스의 샤를) → 859(트란스유라를 루도비코 2세에게, 엔나) → 862(류리크의 노브고로드·폴로츠크·로스토프·무롬) → 863(프로방스의 샤를이 죽음)
// → 867(바이킹의 요크, 콩피에뉴 조약의 코탕탱) → 868(비마라 페레스의 포르투) → 869(동앵글리아) → 870(메르센 조약, 보헤미아 공국(항목이 시작하는 해)) → 872(하랄 미발왕의 노르웨이(하프르스피오르)) → 877(동머시아의 데인인, 바리(876))
// → 878(코임브라, 시라쿠사) → 879(보소의 프로방스 왕국) → 880(리베몽 조약, 구트럼의 에식스, 타란토) → 882(올레그의 키예프·스몰렌스크(renames)) → 883(드레블랴네) → 884(세베랴네, 스바토플루크의 판노니아) → 885(라디미치, 아르메니아 왕국)
// → 886(동로마의 아풀리아·바실리카타·칼라브리아 북부, 앨프레드의 런던과 서머시아) → 888(오도의 즉위와 큰 봉토들(정할 점 M5-①), 상부르군트 왕국) → 893(사모라) → 894(스바토플루크가 죽어 판노니아가 동프랑크로) → 895(마자르의 정착, 페체네그의 흑해 초원)
// → 900(마자르의 판노니아, 시망카스(899)) → 904(나라쉬 경계의 중앙 마케도니아, 아브하지아의 카르틀리, 발레아레스(902~903)) → 907(프레스부르크 전투와 대모라비아의 끝, 드레고비치) → 910(레온 왕국(renames)) → 911(노르망디, 로타링기아가 서프랑크로)
