// ── 476~799 조각 소유표 (작업 M6, 중세 6단계) ─────────────────────────────
// 476년(오도아케르가 로물루스 아우구스툴루스를 폐위)부터 799년 말까지. 계획과 정할 점은 docs/EUROPE_DRAFT.md의 '작업 M 계획'(8절, M6 정할 점은 8.26). 800년부터는 '800~999 조각 소유표'(작업 M5).
// 통째 조각과 앞 표들의 나눈 조각(M5_UNITS의 다게스탄·M4_UNITS·M3_UNITS·M2_UNITS·M1_UNITS·D4_UNITS·D3_UNITS·D2_UNITS·D1_UNITS·E3_UNITS와 E2의 나눈 조각)을 이어 쓰고, 새 선은 바이에른주(DE-BY(476): 프랑켄·슈바벤)와
// 페루자도(IT-PG(476): 스폴레토) 둘만 이 표에서 쓴다. 두 선으로 나눈 조각은 799년에 모두 프랑크 왕국 땅이고 800년부터는 이름이 바뀐 카롤루스 제국이라 이음매가 필요 없다(799년과 800년의 땅이 같은 나라는 단위 목록도 같아
