// ── 기원전 27~기원후 283 조각 소유표 (작업 AN2, 고대 2단계) ─────────────────────────────
// 기원전 27년(천문 연도 −26, 아우구스투스의 원수정)부터 283년 말까지. 계획과 정할 점은 docs/EUROPE_DRAFT.md의 '작업 AN 계획'(9절, 공통 정할 점 9.4, AN2에서 새로 정한 점 9.8). 284년부터는 '284~475 조각 소유표'(작업 AN1).
// 284년 표(T284)의 단위(통째 조각과 앞 표들의 나눈 조각, AN1_UNITS)를 그대로 이어 쓰고, 새 선은 이 표에서만 쓴다: 안탈리아도의 리키아(TR-07(27BC): 파셀리스·올림포스 서쪽, 테르메소스·코르쿠텔리 남쪽)와 알라니아(동경 31.8° 동쪽), 메르신도의 킬리키아 트라케이아(TR-07(27BC)·TR-33(27BC): 라모스강 서쪽, 검토 반영), 바덴뷔르템베르크주의 도나우강 남쪽과 고지 라인강 북안(DE-BW(27BC): 오버슈바벤·보덴호 북안·헤가우·발츠후트, 검토 반영).
// 283년과 284년의 땅이 같은 나라는 단위 목록도 같아 284년 버전이 앞으로 이어진다(284년부터의 도형이 바이트까지 같음). 이 선들로 나눈 조각을 쓰는 로마 제국(안탈리아도·메르신도)과 게르만 부족(바덴뷔르템베르크주)만 283·284년의 땅이 같은데 단위 이름이 달라 284년 이음매(LATER_LIST_SEAMS, 대칭차 0)를 둔다.
// 버전은 그해 말 모습이다. 넘김 해 기준은 AN-⑨: 조약·문서·유증의 해(란데이아 63은 아르메니아의 왕을 로마가 세우는 타협이라 땅은 바뀌지 않음), 조약 없는 정복은 실효 지배가 굳은 해(칸타브리아 전쟁 기원전 19 아그리파, 판노니아 전쟁 기원전 9,
// 브리간테스 71 케리알리스, 웨일스 78 아그리콜라), 종속 왕국은 병합(속주화) 해(갈라티아 기원전 25 아민타스가 죽음, 노리쿰 기원전 16, 파플라고니아 기원전 6, 폰토스 갈라티쿠스 기원전 3, 카파도키아·콤마게네 17, 리키아 43, 트라키아 46, 코티우스 알프스 63, 폰토스 64, 콤마게네 72),
// 전쟁 중 점령과 원정(기원전 12~기원후 9 드루수스·티베리우스·바루스의 게르마니아(정할 점 AN2-①), 83~86 아그리콜라의 테이강 북쪽, 101~102 다키아 전쟁 중의 주둔, 114~117 트라야누스의 메소포타미아·오스로에네, 166~180 마르코만니 전쟁, 208~211 세베루스의 칼레도니아 원정,
// 3세기 고트·헤룰리·보라니의 흑해·에게해 약탈(256 피티우스·257 트라페주스·267 아테네), 252~260 샤푸르 1세의 안티오크·카파도키아 원정, 270~272 팔미라(AN-⑤))는 그리지 않음.
// 근거는 고대 역사가와 금석문(『신군 아우구스투스의 업적록』·스트라본·벨레이우스 파테르쿨루스·대플리니우스·타키투스(『연대기』·『역사』·『아그리콜라』·『게르마니아』 98)·수에토니우스·카시우스 디오·아리아노스(『흑해 주항기』 131)·프톨레마이오스(150 무렵)·
// 『로마 황제 열전』·에우트로피우스·아우렐리우스 빅토르·조시모스·요르다네스)의 서술을 위키백과 등으로 해·주인만 확인했다(줄마다 주석, 근거 URL은 결과 노트와 EUROPE_DRAFT.md 9.8).
// 큰 국경 변화(대략 1만 km² 이상) 때 버전을 나눈다(1만 km² 미만 변화는 사건이 일어난 해의 다음 버전 해에 묶음). 버전 해(천문 연도, 기원전 N년 = 1−N):
// −24(기원전 25 갈라티아 병합, 킬리키아 트라케이아는 아르켈라오스, 살라시) → −18(기원전 19 칸타브리아 전쟁의 끝) → −15(기원전 16 노리쿰) → −14(기원전 15 라이티아·빈델리키아·알프스) → −8(기원전 9 판노니아·달마티아 내륙) → −5(기원전 6 파플라고니아) → −2(기원전 3 폰토스 갈라티쿠스)
// → 17(카파도키아·콤마게네 병합) → 20(이아지게스의 티서강 평원) → 38(콤마게네 복위) → 43(브리타니아 침공, 리키아) → 46(트라키아) → 47(포스 길 선) → 64(폰토스와 콜키스, 61 이케니·63 코티우스 알프스) → 69(베누티우스의 브리간테스) → 71(케리알리스)
// → 72(콤마게네 병합) → 74(아그리 데쿠마테스) → 78(웨일스, 레그니) → 80(아그리콜라의 저지대) → 98(타키투스의 『게르마니아』: 발트·핀·스코네, 아일랜드) → 105(저지대 포기) → 106(다키아 속주) → 114(아르메니아 속주) → 117(아르메니아 복위, 라지카)
// → 118(하드리아누스가 무테니아를 버림) → 142(안토니누스 방벽) → 162(방벽 포기) → 171(하스딩 반달의 코스토보키 땅) → 195(메소포타미아 속주) → 214(오스로에네 병합) → 238(고트족의 흑해 북쪽) → 252(샤푸르 1세의 아르메니아) → 256(크림의 고트)
// → 260(갈리아 제국, 아그리 데쿠마테스 포기) → 269(히스파니아가 클라우디우스 2세에게) → 271(다키아 포기) → 274(아우렐리아누스의 갈리아 회복).
// 이름(항목)만 바뀐 나라: 없음. 왕조가 바뀐 아르메니아(아르탁시아스 → 여러 왕가 → 아르사케스)는 한 항목(AN-⑩, 정할 점 AN2-⑦), 이베리아(파르나바즈 왕조)도 한 항목(iberia-kingdom).
// 종속(AN-④): relations.yaml(갈라티아·카파도키아·폰토스·파플라고니아·콤마게네·리키아·트라키아·노리쿰·코티우스·브리타니아의 종속 왕국들·보스포로스·아르메니아·이베리아·라지카·다키아(89~105)·오스로에네(165~213)).
// 일부러 비운 곳: 284~475 표와 같은 곳(스발바르·얀마옌·프란츠요제프 제도·북캅카스 산지(알라니아)·체르케스 해안·모르도바·펜자·탐보프·오렌부르크 초원·바시키르·대페름·페름 지방 남부·니즈니노브고로드주 남부·볼가 중류·핀란드 북부·동부·노를란드·노르웨이·페로 제도·
// 스웨덴(스베알란드 포함)·아이슬란드·우스튜그·뱌트카·노브고로드 북쪽 땅·세우타·멜리야·카나리아 제도·아소르스·마데이라, 체르니히우·수미 북부·쿠르스크·지토미르(키이우 문화), 코르두에네·자브디케네·모그소에네(파르티아·사산의 종주))에 더해:
