// 기원전 27~기원후 237년 키이우·체르카시·폴타바·하르키우·벨고로드 숲초원과 볼히니아(고트족 전 근거 약함, 정할 점 AN2-⑧), 기원전 27~기원후 194년 마르딘(니시비스, 파르티아 직할), 252년부터 대아르메니아(샤푸르 1세의 아르메니아 왕 호르미즈드 아르다시르·나르세, 284년 표와 이음).
// 쪼개지 않은 근사(각 1만 km² 미만, 넓이는 어림. 1만 km²를 넘는 것은 정할 점 AN2-①~⑭로 올림, EUROPE_DRAFT.md 9.8):
// - 브리튼: 43년 버전의 남동부는 서경 1.6° 동쪽·북위 52.62° 남쪽 조각(햄프셔·와이트섬·옥스퍼드·노샘프턴 포함, 베스파시아누스의 43~47 남서부 원정은 47년), 47년 포스 길 선에 데번·콘월(55 엑서터)과 웨일스 접경(48~51 데케앙글리·코르노비이, 슈롭셔·헤리퍼드·체셔 약 8천 km²)을 넣음,
//   브리간테스(43~68)는 북위 53.3° 북쪽 조각과 컴브리아·노섬벌랜드(파리시 포함, 더비셔·체셔는 47년 로마), 레그니(코기둡누스, 43~77, 서식스 약 4.2천 km²), 이케니(노퍽 약 5.6천 km², 61 병합은 64년 버전에 묶음, 서퍽 북부는 43년 로마),
