// - 갈리아·게르마니아: 해양 알프스(알프마리팀·망통·모나코 약 4.6천 km², 기원전 14 정복)는 처음부터 로마, 코티우스 알프스는 오트잘프(약 5.5천 km², 수사 계곡 약 1.7천 km²는 로마째), 63 코티우스 2세가 죽은 뒤 병합은 64년 버전,
//   오버슈바벤·보덴호 북안·고지 라인강 북안(약 7.4천 km², 새 선 DE-BW(27BC))은 기원전 15 빈델리키아와 함께 로마(검토 반영), 헬데를란트의 라인강 북쪽(펠뤼버·아흐테르후크 약 3.2~3.9천 km² 어림, 리메스 밖)은 284년 표처럼 로마째(FIX 후보),
