//   서헤르체고비나·트레비녜(약 4.7천 km²)는 달마티아 내륙과 함께 기원전 9, 오스트리아의 도나우강 북쪽(약 1.3만 km²)은 정할 점 AN2-⑬, 무테니아 서쪽의 트란살루타누스 리메스(200 무렵~245, 약 5.7천 km²)는 그리지 않음,
