// 흑룡강 북쪽·하류(외만주: 아르군강 합류점에서 스타노보이산맥을 따라 우다만까지의 남쪽, 아이훈 조약(1858)·베이징 조약(1860)으로 러시아)를 뺀다.
// 외만주는 2026-10-09(작업 C1)부터 shared.mjs의 OUTER_MANCHURIA를 쓰고, 청 도형이 1689~1857년에 갖는다(우다강 유역 UDA는 빼고 아무도 칠하지 않음. 전에는 1691~1857년 비어 있었다).
// 1789~1814년(작업 E3)에도 같은 손 도형을 쓴다(카자흐 초원·캅카스 남쪽 등 권역 바깥선 밖은 1815년처럼 대략적인 추정)
// 2026-10-06(작업 D1): 1700~1788년의 러시아 차르국·러시아 제국도 같은 손 도형(네르친스크 조약 경계)을 썼다(카자흐 초원·중앙아시아·투바·사할린·추코트카와 흑해 쪽 해안 부스러기까지 들어간 근사).
// 같은 날(작업 D2와 그 검토 반영): 1600~1917년 모두 이 손 도형을 아래 '시베리아 진출 단계'(SIBERIA_ZONES)로 잘라 쓴다(1789년부터의 카자흐 초원·중앙아시아·투바·사할린·세베르나야제믈랴 근사도 고침).
