// 1788년까지의 러시아 차르국·러시아 제국의 권역 바깥선 밖은 위 손 도형(RUSSIA_PRE1860)을 단계마다 넓어지는 구역의 합집합으로 자른다. 구역은 [해, 링들]이고 그 해 말부터 러시아 땅이다.
