// 영국은 1707~1800 그레이트브리튼 왕국(1700~1706년은 잉글랜드·스코틀랜드 항목, 작업 D1), 1801~1921 아일랜드를 합친 연합 왕국, 1922년부터 아일랜드 자유국을 뺀 모습으로 모두 소유표에서 만든다(작업 B1, 전에는 1922년 버전이 E1 도형 UK_1922. 조각 묶음이 같아 도형도 같음)
export const versions = {
  'grand-duchy-of-moscow': withEast(russiaPlan('grand-duchy-of-moscow')),
  'russia-tsardom': withEast(russiaPlan('russia-tsardom')),
  russia: withEast(russiaPlan()),
  'soviet-union': withEast(sovietPlan()),
  'russia-fed': [[1992, 2008, U(outside(RUSSIA_FED), RF_EU)], [2008, null, U(outside(RUSSIA_FED_2008), RF_EU)]],
  france: tableVersions('france').map(([from, to, list], i, all) => {
    if (i === all.length - 1 && (from !== 1947 || to !== null)) throw new Error('europe.mjs: 프랑스의 마지막 버전이 1947~이 아님');
    return [from, to, from === 1947 ? U(FRANCE_1947, geomOfUnit(IT_IM.망통)) : build(list)];
  }),
  // 이탈리아 공화국: 1946년 6월 국민 투표로 왕국이 공화국으로 바뀜(이름만 바뀜, 땅은 1945년 말과 같음). 1946년 버전은 B1처럼 왕국의 1945년 단위 목록으로 만들고(같은 땅),
  // 1947년(파리 강화 조약)부터는 소유표(작업 B2)
  'italy-republic': tableVersions('italy-republic').map(([from, to, list], i) => {
    if (i === 0 && (from !== 1946 || to !== 1947)) throw new Error('europe.mjs: 이탈리아 공화국의 첫 버전이 1946~1947이 아님');
    return [from, to, build(i === 0 ? tableVersions('italy').at(-1)[2] : list)];
  }),
  ...Object.fromEntries(TABLE_ENTITIES.map((id) => [id, tableVersions(id).map(([from, to, list]) => [from, to, build(list), ...(DISPUTED.has(id) ? ['disputed'] : [])])])),
};

// 빈 땅 검사 구역 (DESIGN.md §5.4): 권역 바깥선(domain, 모든 조각의 합)에서 그해 주인 없는 단위(소유표의 null)를 뺀 곳.
// 주인 없는 단위가 같은 기간마다 구역 하나. 1600년부터 지금까지(뼈대를 채운 구간, 2026-10-02 작업 E3에서 1789년까지, 2026-10-03 작업 B1에서 1945년까지, 같은 날 작업 B2에서 1991년까지,
