// 1300~1399년(작업 M2)에 더: 1300~1323년 대페름, 1308~1334년 일한국 직할기의 아나톨리아 중부, 1375년부터 아다나·오스마니예(맘루크), 1300~1397년 포티(1300~1399 표 머리 주석)
